mapper.select:
select t1.id, t1.status, t1.origin_code, t1.source_id, t1.task_type, t1.task_status, t1.task_count, t1.code, t1.dept_id, t1.dept_name, t1.auditor, t1.create_by, t1.create_time, t1.update_by, t1.update_time, t1.remark, t1.del_flag, t1.is_reassemble, t1.relation_task_code, t1.check_type, t2.tray_type, t1.update_by as executeName from t_task t1 left join t_check_delivery t2 on t1.source_id = t2.id left join t_material a on t2.material_id = a.id
t1.del_flag = '0' and t1.origin_code = #{originCode} and t1.source_id = #{sourceId} and t1.task_type = #{taskType} and t1.task_status = #{taskStatus} and t1.task_count = #{taskCount} and t1.code like concat('%',#{code},'%') and a.code like concat('%',#{materialCode},'%') and a.name like concat('%',#{materialName},'%') and t1.dept_id = #{deptId} and t1.status = #{status} and t1.auditor = #{auditor} and t1.status = #{status}
and t1.task_status in (${checkDeliveryStatus})
and t2.area_id = #{areaId}
and DATE_FORMAT(t1.create_time,'%Y-%m-%d') between DATE_FORMAT(#{startTime},'%Y-%m-%d') and DATE_FORMAT(#{endTime},'%Y-%m-%d')
and t1.check_type = #{checkType}
order by t1.create_time desc

select t1.code, t1.task_type, t1.task_status, t1.task_count, t1.dept_id, t1.dept_name, t1.origin_code, t1.remark, t2.material_id, t2.location_id, t2.tray_id, t2.duty_personnel, t2.batch_number, t2.predict_count, t2.actual_count, t2.status, t3.code, t1.remark, t1.relation_task_code, t1.create_by, t1.create_time from t_task t1 inner join t_task_detail t2 on t1.id = t2.task_id left join t_tray t3 on t2.tray_id = t3.id
t1 .del_flag ='0' and t2.del_flag ='0' and t1.task_type = #{taskType} and t1.task_status = #{taskStatus}
order by t1.create_time desc
